            "full_match": m,
            "seen": seen,
            "vars_info": vars_info,
            "start": m.start(),
            "end": m.end(),
            "text": m.group(0)
        })
    return matches

def compute_line_col(content, offset):
    before = content[:offset]
    line = before.count('\\n')
    last_nl = before.rfind('\\n')
    if last_nl == -1:
        col = offset
    else:
        col = offset - last_nl -1
    return line, col

def get_line_text(content, line_no):
