                    result["replacement"]=repl
                    result["replacementOffsets"]={"start": start, "end": end}
                all_results.append(result)
            continue
        if rewrite:
            new_content = content
            for mm in sorted(matches, key=lambda x: x["start"], reverse=True):
                s = mm["start"]; e = mm["end"]
                repl = rewrite
                for n,v in mm["seen"].items():
                    repl = repl.replace(f"${n}", v).replace(f"$$${n}", v)
                new_content = new_content[:s] + repl + new_content[e:]
            if update_all:
                if fpath != "STDIN":
                    try:
                        Path(fpath).write_text(new_content)
                        print(f"Applied {len(matches)} changes")
                    except Exception as ex:
                        sys.stderr.write(f"Failed to write {fpath}: {ex}\n")
                else:
                    print(new_content)
                continue
            else:
                print(fpath)
                old_lines = content.splitlines()
                new_lines = new_content.splitlines()
                print(f"@@ -0,{len(old_lines)} +0,{len(new_lines)} @@")
                max_len = max(len(old_lines), len(new_lines))
                for i in range(max_len):
                    old = old_lines[i] if i < len(old_lines) else ""
                    new = new_lines[i] if i < len(new_lines) else ""
                    lnum = i+1
                    if old == new:
                        print(f"{lnum} {lnum}│ {old}")
                    else:
                        if old:
                            print(f"{lnum}  │-{old}")
                        if new:
                            print(f"  {lnum}│+{new}")
                continue
        if before>0 or after>0:
            intervals=[]
            for mm in matches:
                line,_ = compute_line_col(content, mm["start"])
                s = max(0, line-before); e = line+after
                line_end,_ = compute_line_col(content, mm["end"])
                e = max(e, line_end+after)
                intervals.append((s,e))
            intervals.sort()
            merged=[]
            for s,e in intervals:
                if not merged:
                    merged.append([s,e])
                else:
                    last=merged[-1]
                    if s <= last[1]+1:
                        last[1]=max(last[1], e)
                    else:
                        merged.append([s,e])
            lines = content.splitlines()
            for s,e in merged:
                for ln in range(s, min(e+1, len(lines))):
                    print(f"{fpath}:{ln+1}:{lines[ln]}")
            continue
        for mm in matches:
            line,_ = compute_line_col(content, mm["start"])
            print(f"{fpath}:{line+1}:{mm['text']}")

    if json_opt is not None:
        style = json_opt
        if style is None or style == "" or style == "pretty":
            print(json.dumps(all_results, indent=2))
        elif style == "compact":
            print(json.dumps(all_results, separators=(',', ':')))
        elif style == "stream":
            for r in all_results:
                print(json.dumps(r))

def do_completions(shell):
    if not shell:
        sh_env = os.environ.get("SHELL","")
        if "bash" in sh_env:
            shell="bash"
        elif "zsh" in sh_env:
            shell="zsh"
        elif "fish" in sh_env:
            shell="fish"
        elif "elvish" in sh_env:
            shell="elvish"
        elif "powershell" in sh_env or "pwsh" in sh_env:
            shell="powershell"
        else:
            sys.stderr.write("Error: Can not infer which shell to generate completions.\nHelp: Either specify shell flavor by `sg completions [SHELL]` or set correct `SHELL` environment.\nSee also: https://ast-grep.github.io/reference/cli.html\n\n")
            sys.exit(2)
    key = shell
    txt = COMP.get(key, "")
    if not txt:
        # try loading from file fallback
        for cand in [f"/tmp/comp_{key}.txt", "/tmp/comp_bash.txt"]:
            p = Path(cand)
            if p.exists():
                txt = p.read_text()
                break
    print(txt)

def find_project_root(start=None):
    cur = Path(start) if start else Path.cwd()
    for _ in range(20):
        if (cur / "sgconfig.yml").exists():
            return cur
        if cur.parent == cur:
            break
        cur = cur.parent
    return None

def parse_sgconfig(root):
    txt = (root / "sgconfig.yml").read_text()
    rule_dirs=[]; test_dirs=[]; util_dirs=[]
    mode=None
    for line in txt.splitlines():
        stripped=line.strip()
        if stripped.startswith("ruleDirs:"):
            mode="rule"; continue
        if stripped.startswith("testConfigs:"):
            mode="test"; continue
        if stripped.startswith("utilDirs:"):
            mode="util"; continue
        if "testDir:" in stripped:
            idx=stripped.find("testDir:")
            after=stripped[idx+len("testDir:"):].strip()
            test_dirs.append(after)
            continue
        if stripped.startswith("- "):
            val=stripped[2:].strip()
            if mode=="rule":
                rule_dirs.append(val)
            elif mode=="util":
                util_dirs.append(val)
    return rule_dirs, test_dirs, util_dirs

def do_new_project(argv):
    cwd = Path.cwd()
    if (cwd / "sgconfig.yml").exists():
        sys.stderr.write("Error: ast-grep project already exists.\nHelp: You are already inside a sub-folder of an ast-grep project. Try finding sgconfig.yml in ancestor directory?\nSee also: https://ast-grep.github.io/guide/scan-project.html\n\n")
        sys.exit(3)
    p=cwd.parent
    while p!=p.parent:
        if (p / "sgconfig.yml").exists():
            sys.stderr.write("Error: ast-grep project already exists.\nHelp: You are already inside a sub-folder of an ast-grep project. Try finding sgconfig.yml in ancestor directory?\nSee also: https://ast-grep.github.io/guide/scan-project.html\n\n")
            sys.exit(3)
        p=p.parent
    rules=cwd/"rules"; tests=cwd/"rule-tests"; utils=cwd/"utils"
    rules.mkdir(exist_ok=True); tests.mkdir(exist_ok=True); utils.mkdir(exist_ok=True)
    sgcontent=f"ruleDirs:\n- {rules}\ntestConfigs:\n- testDir: {tests}\nutilDirs:\n- {utils}\n"
    (cwd/"sgconfig.yml").write_text(sgcontent)
    print("Creating a new ast-grep project...")
    print("Your new ast-grep project has been created!")

def do_new_rule(argv):
    name=None; lang=None; yes=False
    i=0
    while i < len(argv):
        a=argv[i]
        if a in ("-y","--yes"):
            yes=True; i+=1
        elif a in ("-l","--lang"):
            if i+1 < len(argv):
                lang=argv[i+1]; i+=2
            else:
                i+=1
        elif a.startswith("--lang="):
            lang=a.split("=",1)[1]; i+=1
        elif a.startswith("-"):
            i+=1
        else:
            if name is None:
                name=a
            i+=1
    if not name or not lang:
        if not name:
            sys.stderr.write("error: the following required arguments were not provided:\n  <NAME>\n\nUsage: executable new rule [OPTIONS] <NAME>\n\nFor more information, try '--help'.\n"); sys.exit(2)
        if not lang:
            sys.stderr.write("error: the following required arguments were not provided:\n  --lang <LANG>\n\nUsage: executable new rule --lang <LANG> <NAME>\n\nFor more information, try '--help'.\n"); sys.exit(2)
    root=find_project_root()
    if not root:
        sys.stderr.write("Error: No ast-grep project configuration is found.\nHelp: You need to create an ast-grep project for this command. Try `sg new` to create one.\nSee also: https://ast-grep.github.io/guide/scan-project.html\n\n"); sys.exit(3)
    rule_dirs, test_dirs, _ = parse_sgconfig(root)
    if not rule_dirs:
        sys.stderr.write("Error: No rule directory configured\n"); sys.exit(3)
    rd=rule_dirs[0]
    rd_path=Path(rd) if Path(rd).is_absolute() else root/rd
    rd_path.mkdir(parents=True, exist_ok=True)
    full_lang=full_lang_name(lang)
    content=f"# yaml-language-server: $schema=https://raw.githubusercontent.com/ast-grep/ast-grep/main/schemas/rule.json\n\nid: {name}\nmessage: Add your rule message here....\nseverity: error # error, warning, info, hint\nlanguage: {full_lang}\nrule:\n  pattern: Your Rule Pattern here...\n# utils: Extract repeated rule as local utility here.\n# note: Add detailed explanation for the rule."
    (rd_path / f"{name}.yml").write_text(content)
    print(f"Created rules at {rd_path / f'{name}.yml'}")
    if not test_dirs:
        sys.stderr.write("Error: No test file directory is configured.\nHelp: Fail to create a test file because the project `sgconfig.yml` does not specify any test configuration.\nSee also: https://ast-grep.github.io/guide/test-rule.html\n\n")
        return
    td=test_dirs[0]
    td_path=Path(td) if Path(td).is_absolute() else root/td
    td_path.mkdir(parents=True, exist_ok=True)
    test_content=f"id: {name}\nvalid:\n- \"valid code\"\ninvalid:\n- \"invalid code\"\n"
    tfile=td_path / f"{name}-test.yml"
    if tfile.exists():
        sys.stderr.write(f"Error: File `{tfile}` already exists.\nHelp: The item you want to create already exists. Try editing the existing file or create a new one with a different name?\n\n"); sys.exit(1)
    tfile.write_text(test_content)
    print(f"Created test at {tfile}")

