def main():
    argv = sys.argv
    if "--version" in argv or "-V" in argv:
        print(VERSION); sys.exit(0)

    # help handling
    if len(argv)>=2 and argv[1]=="help":
        if len(argv)>=3:
            sub=argv[2]
            if sub=="run":
                print(get_help("run_long.txt")); sys.exit(0)
            elif sub=="scan":
                print(get_help("scan_long.txt")); sys.exit(0)
            elif sub=="test":
                print(get_help("test_long.txt")); sys.exit(0)
            elif sub=="new":
                if len(argv)>=4:
                    sub2=argv[3]
                    if sub2=="project":
                        print(get_help("new_project_long.txt")); sys.exit(0)
                    elif sub2=="rule":
                        print(get_help("new_rule_long.txt")); sys.exit(0)
                    elif sub2=="test":
                        print(get_help("new_test_long.txt")); sys.exit(0)
                    elif sub2=="util":
                        print(get_help("new_util_long.txt")); sys.exit(0)
                    else:
                        print(get_help("new_long.txt")); sys.exit(0)
                else:
                    print(get_help("new_long.txt")); sys.exit(0)
            elif sub=="lsp":
                print(get_help("lsp_long.txt")); sys.exit(0)
            elif sub=="completions":
                print(get_help("comp_long.txt")); sys.exit(0)
            else:
                print(get_help("main_long.txt")); sys.exit(0)
        else:
            print(get_help("main_long.txt")); sys.exit(0)

    # detect subcommand chain
    known=["run","scan","test","new","lsp","completions"]
    known_new_sub=["project","rule","test","util"]
    subcommands=[]
    idx=1
    while idx < len(argv):
        tok=argv[idx]
        if tok.startswith("-"):
            idx+=1
            continue
        if tok in known:
            subcommands.append(tok)
            idx+=1
            if tok=="new" and idx < len(argv) and argv[idx] in known_new_sub:
                subcommands.append(argv[idx])
                idx+=1
            continue
        idx+=1

    has_long="--help" in argv
    has_short="-h" in argv and not has_long

    if has_long or has_short:
        is_long=has_long
        key=None
        if not subcommands:
            key="main_long.txt" if is_long else "main_short.txt"
        else:
            if subcommands==["run"]:
                key="run_long.txt" if is_long else "run_short.txt"
            elif subcommands==["scan"]:
                key="scan_long.txt" if is_long else "scan_short.txt"
            elif subcommands==["test"]:
                key="test_long.txt" if is_long else "test_short.txt"
            elif subcommands==["new"]:
                key="new_long.txt" if is_long else "new_short.txt"
            elif subcommands==["new","project"]:
                key="new_project_long.txt" if is_long else "new_project_short.txt"
            elif subcommands==["new","rule"]:
                key="new_rule_long.txt" if is_long else "new_rule_short.txt"
            elif subcommands==["new","test"]:
                key="new_test_long.txt" if is_long else "new_test_short.txt"
            elif subcommands==["new","util"]:
                key="new_util_long.txt" if is_long else "new_util_short.txt"
            elif subcommands==["lsp"]:
                key="lsp_long.txt" if is_long else "lsp_short.txt"
            elif subcommands==["completions"]:
                key="comp_long.txt" if is_long else "comp_short.txt"
            else:
                key="main_long.txt" if is_long else "main_short.txt"
        txt=get_help(key)
        if txt:
            print(txt); sys.exit(0)
        else:
            print(get_help("main_long.txt")); sys.exit(0)

    # determine command
    cmd=None
    cmd_args=[]
    for i in range(1,len(argv)):
        if argv[i] in known:
            cmd=argv[i]
            cmd_args=argv[i+1:]
            break
    if cmd is None:
        cmd="run"
        cmd_args=argv[1:]

    if cmd=="run":
        parsed=parse_run_args(cmd_args)
        do_run(parsed)
    elif cmd=="completions":
        shell=None
        for a in cmd_args:
            if not a.startswith("-"):
                shell=a
                break
        # COMP dict already
        global COMP
        # Try to get from HELP_FILES? We'll load from files if COMP empty
        if not COMP.get(shell):
            # load from /tmp files
            for cand in [f"/tmp/comp_{shell}.txt", f"/tmp/comp_bash.txt"]:
                p=Path(cand)
                if p.exists():
                    COMP[shell]=p.read_text()
                    break
        # If still empty, try shell inference
        if shell is None:
            sh_env=os.environ.get("SHELL","")
            if "bash" in sh_env:
                shell="bash"
            elif "zsh" in sh_env:
                shell="zsh"
            elif "fish" in sh_env:
                shell="fish"
            elif "elvish" in sh_env:
                shell="elvish"
            elif "powershell" in sh_env or "pwsh" in sh_env:
                shell="powershell"
            else:
                sys.stderr.write("Error: Can not infer which shell to generate completions.\nHelp: Either specify shell flavor by `sg completions [SHELL]` or set correct `SHELL` environment.\nSee also: https://ast-grep.github.io/reference/cli.html\n\n")
                sys.exit(2)
        txt=COMP.get(shell, "")
        if not txt:
            # fallback loads
            p=Path(f"/tmp/comp_{shell}.txt")
            if p.exists():
                txt=p.read_text()
            else:
                # try bash
                p=Path("/tmp/comp_bash.txt")
                txt=p.read_text() if p.exists() else ""
        print(txt)
    elif cmd=="new":
        sub=None
        sub_args=[]
        for i,a in enumerate(cmd_args):
            if not a.startswith("-") and a in known_new_sub:
                sub=a
                sub_args=cmd_args[i+1:]
                break
        if sub is None:
            do_new_project(cmd_args)
        else:
            if sub=="project":
                do_new_project(sub_args)
            elif sub=="rule":
                do_new_rule(sub_args)
            elif sub=="test":
                do_new_test(sub_args)
            elif sub=="util":
                do_new_util(sub_args)
    elif cmd=="lsp":
        try:
            import time
            while True:
                time.sleep(1)
        except KeyboardInterrupt:
            sys.exit(0)
    elif cmd=="scan":
        # minimal scan
        inline=None; rule_file=None; paths=[]; json_opt=None; report_style="rich"; filter_regex=None
        i=0
        while i < len(cmd_args):
            a=cmd_args[i]
            if a=="--inline-rules":
                inline=cmd_args[i+1] if i+1 < len(cmd_args) else ""; i+=2
            elif a.startswith("--inline-rules="):
                inline=a.split("=",1)[1]; i+=1
            elif a in ("-r","--rule"):
                rule_file=cmd_args[i+1] if i+1 < len(cmd_args) else ""; i+=2
            elif a.startswith("--rule="):
                rule_file=a.split("=",1)[1]; i+=1
            elif a.startswith("--json"):
                if "=" in a:
                    json_opt=a.split("=",1)[1]
                else:
                    json_opt="pretty"
                i+=1
            elif a.startswith("--report-style"):
                if "=" in a:
                    report_style=a.split("=",1)[1]; i+=1
                else:
                    report_style=cmd_args[i+1] if i+1 < len(cmd_args) else "rich"; i+=2
            elif a.startswith("--filter"):
                if "=" in a:
                    filter_regex=a.split("=",1)[1]; i+=1
                else:
                    filter_regex=cmd_args[i+1] if i+1 < len(cmd_args) else ""; i+=2
            elif a.startswith("--"):
                if "=" in a:
                    i+=1
                else:
                    if i+1 < len(cmd_args) and not cmd_args[i+1].startswith("-"):
                        i+=2
                    else:
                        i+=1
            elif a.startswith("-"):
                i+=1
            else:
                paths.append(a); i+=1
        if not paths:
            paths=["."]
        rules=[]
        def parse_rule_yaml(text):
            docs=text.split("---")
            res=[]
            for doc in docs:
                if not doc.strip():
                    continue
                id_m=re.search(r'^\s*id\s*:\s*(.+)\s*$', doc, re.MULTILINE)
                lang_m=re.search(r'^\s*language\s*:\s*(.+)\s*$', doc, re.MULTILINE)
                pat_m=re.search(r'^\s*pattern\s*:\s*(.+)\s*$', doc, re.MULTILINE)
                msg_m=re.search(r'^\s*message\s*:\s*(.+)\s*$', doc, re.MULTILINE)
                sev_m=re.search(r'^\s*severity\s*:\s*(.+)\s*$', doc, re.MULTILINE)
                fix_m=re.search(r'^\s*fix\s*:\s*(.+)\s*$', doc, re.MULTILINE)
                fix_template_m=re.search(r'^\s*template\s*:\s*["\']?(.+?)["\']?\s*$', doc, re.MULTILINE)
                rid=id_m.group(1).strip() if id_m else "unknown"
                lang_val=lang_m.group(1).strip() if lang_m else "js"
                pat_val=pat_m.group(1).strip() if pat_m else ""
                msg_val=msg_m.group(1).strip() if msg_m else ""
                sev_val=sev_m.group(1).strip().split()[0] if sev_m else "warning"
                fix_val=fix_m.group(1).strip() if fix_m else ""
                if fix_template_m and not fix_val:
                    fix_val=fix_template_m.group(1).strip()
                res.append({"id": rid, "language": lang_val, "pattern": pat_val, "message": msg_val, "severity": sev_val, "fix": fix_val})
            return res
        if inline:
            rules.extend(parse_rule_yaml(inline))
        if rule_file:
            try:
                txt=Path(rule_file).read_text()
                rules.extend(parse_rule_yaml(txt))
            except FileNotFoundError:
                sys.stderr.write(f"Error: Cannot read rule {rule_file}\nHelp: The rule file either does not exist or cannot be opened.\nSee also: https://ast-grep.github.io/guide/rule-config.html\n\n✖ Caused by\n╰▻ No such file or directory (os error 2)\n\n")
                sys.exit(2)
        if not rules:
            root=find_project_root()
            if not root:
                sys.stderr.write("Error: No ast-grep project configuration is found.\nHelp: You need to create an ast-grep project for this command. Try `sg new` to create one.\nSee also: https://ast-grep.github.io/guide/scan-project.html\n\n")
                sys.exit(3)
            rule_dirs,_,_=parse_sgconfig(root)
            for rd in rule_dirs:
                rd_path=Path(rd) if Path(rd).is_absolute() else root/rd
                if not rd_path.exists():
                    continue
                for yfile in rd_path.glob("*.yml"):
                    try:
                        rules.extend(parse_rule_yaml(yfile.read_text()))
                    except:
                        pass
                for yfile in rd_path.glob("*.yaml"):
                    try:
                        rules.extend(parse_rule_yaml(yfile.read_text()))
                    except:
                        pass
        if filter_regex:
            try:
                fre=re.compile(filter_regex)
                rules=[r for r in rules if fre.search(r["id"])]
                if not rules:
