def pattern_to_regex(pat):
    placeholder_re = re.compile(r'\$\$\$[A-Z_][A-Z0-9_]*|\$[A-Z_][A-Z0-9_]*')
    regex_parts = []
    last = 0
    vars_info = []
    counter = 0
    for m in placeholder_re.finditer(pat):
        s, e = m.span()
        lit = pat[last:s]
        if lit:
            regex_parts.append(re.escape(lit))
        ph = m.group()
        if ph.startswith('$$$'):
            name = ph[3:]
            is_multi = True
        else:
            name = ph[1:]
            is_multi = False
        group_name = f"G{counter}_{name}"
        counter+=1
        if is_multi:
            regex_parts.append(f'(?P<{group_name}>.*?)')
        else:
            regex_parts.append(f'(?P<{group_name}>.+?)')
        vars_info.append({"name": name, "is_multi": is_multi, "group": group_name, "placeholder": ph})
        last = e
    lit = pat[last:]
    if lit:
        regex_parts.append(re.escape(lit))
    regex_str = ''.join(regex_parts)
    return regex_str, vars_info

