    regex_str, vars_info = pattern_to_regex(pattern)
    if strictness != "cst":
        regex_str = regex_str.replace(r'\ ', r'\s*')
    try:
        r = re.compile(regex_str, re.DOTALL)
    except re.error:
        return []
    matches = []
    for m in r.finditer(content):
        gd = m.groupdict()
        seen = {}
        ok = True
        for vi in vars_info:
            name = vi["name"]
            gname = vi["group"]
            val = gd.get(gname, "")
            if name in seen:
                if seen[name] != val:
                    ok=False
                    break
            else:
                seen[name]=val
        if not ok:
            continue
        matches.append({
            "full_match": m,
            "seen": seen,
            "vars_info": vars_info,
            "start": m.start(),
            "end": m.end(),
            "text": m.group(0)
        })
    return matches

def compute_line_col(content, offset):
    before = content[:offset]
    line = before.count('\n')
    last_nl = before.rfind('\n')
    if last_nl == -1:
        col = offset
    else:
        col = offset - last_nl -1
    return line, col

